import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in as the seeded member, so the request context holds the session cookie
  await expectStatus(await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }), 200);
  const { cookies: before } = await request.storageState();
  expect(before.find((c) => c.name === "session")?.value).toBeTruthy();

  // Act: sign out
  const response = await request.post("/api/auth/logout");

  // Assert: 204, and the session cookie is cleared
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "logout sets the session cookie").toBeDefined();
  const cookieHeader = cookie!.value.toLowerCase();
  expect(cookieHeader.startsWith('session=""') || cookieHeader.includes("max-age=0")).toBe(true);
});
